// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(address caller, address target, bool freeze) public {
        vm.assume(caller != address(0));
        vm.assume(target != address(0));
        vm.assume(caller != c.owner());
        vm.prank(caller);
        bool ok;
        try c.freezeAccount(target, freeze) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
